              borderWidth: 2,
              pointRadius: 2.2,
              pointHoverRadius: 3.2,
              pointBorderWidth: 0,
              tension: 0.15,
              order: 0
            },
            {
              type: 'line',
              label: 'Battery storage LCOE (4h) — 2023 USD/MWh',
              yAxisID: 'yCost',
              data: battery,
              borderColor: colors.battery,
              backgroundColor: colors.battery,
              borderWidth: 2,
              pointRadius: 2.2,
              pointHoverRadius: 3.2,
              pointBorderWidth: 0,
              tension: 0.12,
              order: 0
            },
            {
              type: 'line',
              label: 'Solar PV capacity — cumulative (GW)',
              yAxisID: 'yCap',
              data: solarGW,
              borderColor: colors.solarCap,
              backgroundColor: colors.solarCap,
              borderWidth: 2,
              borderDash: [6,4],
              pointRadius: 0,
              tension: 0.15,
              order: 2
            },
            {
              type: 'line',
              label: 'Onshore wind capacity — cumulative (GW)',
              yAxisID: 'yCap',
              data: windGW,
              borderColor: colors.windCap,
              backgroundColor: colors.windCap,
              borderWidth: 2,
              borderDash: [6,4],
              pointRadius: 0,
              tension: 0.15,
              order: 2
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'index', intersect: false },
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(ctx) {
                  var ds = ctx.dataset;
                  var v = ctx.parsed.y;
                  if (ds.yAxisID === 'ySubsidy') return ds.label + ': ' + fmtBn(v);
                  if (ds.yAxisID === 'yCap') return ds.label + ': ' + fmtGW(v);
