      width: 44px; height: 44px; border-radius: 12px;
      background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.08);
      color: var(--text); cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      backdrop-filter: blur(10px);
      transition: transform 0.15s ease, background 0.15s ease;
    }
    html.theme-light .viz-menu-toggle {
      background: rgba(15,23,42,0.04); border: 1px solid rgba(15,23,42,0.08);
    }
    .viz-menu-toggle:hover { transform: translateY(-1px); background: rgba(255,255,255,0.10); }
    html.theme-light .viz-menu-toggle:hover { background: rgba(15,23,42,0.07); }

    .viz-menu-dropdown {
      position: absolute; top: 54px; right: 0;
      width: 210px; padding: 8px;
      background: rgba(20,20,20,0.92);
      border: 1px solid rgba(255,255,255,0.10);
      border-radius: 12px;
      box-shadow: 0 16px 48px rgba(0,0,0,0.35);
      transform: translateY(-6px); opacity: 0; pointer-events: none;
      transition: opacity 0.15s ease, transform 0.15s ease;
      backdrop-filter: blur(12px);
    }
    html.theme-light .viz-menu-dropdown {
      background: rgba(255,255,255,0.92);
      border: 1px solid rgba(15,23,42,0.10);
      box-shadow: 0 16px 48px rgba(15,23,42,0.18);
    }
    .viz-menu-dropdown.open { opacity: 1; pointer-events: auto; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 12px; border: none; border-radius: 10px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* ===== Custom layout for this chart ===== */
    .page {
      max-width: 1200px;
      margin: 0 auto;
      padding: 40px 22px 56px;
    }

    header.hero {
      display: grid;
      gap: 12px;
      margin-bottom: 18px;
    }

    .kicker {
      font-size: 12px;
      letter-spacing: 0.10em;
      text-transform: uppercase;
      color: var(--text-secondary);
    }

    .subtitle {
      max-width: 95ch;
      color: var(--text-secondary);
      font-size: 14px;
    }

    .meta {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
      color: var(--text-secondary);
      font-size: 12px;
      margin-top: 4px;
    }

    .legend-pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 10px;
      border-radius: 999px;
      background: rgba(255,255,255,0.04);
      border: 1px solid rgba(255,255,255,0.06);
    }
    html.theme-light .legend-pill {
      background: rgba(15,23,42,0.03);
      border: 1px solid rgba(15,23,42,0.07);
    }

    .swatch {
      width: 10px;
      height: 10px;
      border-radius: 3px;
      background: var(--accent);
    }

    .chart-wrap {
      height: 560px;
      position: relative;
    }

    .chart-note {
      margin-top: 10px;
      display: grid;
      grid-template-columns: 1fr;
      gap: 8px;
      color: var(--text-secondary);
      font-size: 12px;
    }

    .annotation-box {
      display: grid;
      gap: 4px;
      padding: 10px 12px;
      border-radius: 10px;
      background: rgba(16,185,129,0.08);
      border: 1px solid rgba(16,185,129,0.16);
    }
    .annotation-box strong { color: var(--text); font-weight: 650; }

    @media (max-width: 740px) {
      .page { padding: 26px 14px 44px; }
      .chart-wrap { height: 540px; }
    }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>
  <main id="main-content">

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <main id="main-content" role="main">
    <div class="page">
      <section class="animate" aria-label="Title and context">
        <header class="hero">
          <div class="kicker">Climate economics • 2010–2024</div>
          <h1>Renewables’ cost collapse, rapid scale-up — and persistent fossil subsidies</h1>
          <p class="subtitle">
            Levelized cost of energy (LCOE) for <strong>solar PV</strong>, <strong>onshore wind</strong>, and <strong>4-hour battery storage</strong>
            (2023 real USD/MWh) shown alongside cumulative installed capacity (GW). The shaded band represents the cost range of new-build
            fossil generation (coal + gas CCGT). Bars show annual global fossil fuel subsidies (nominal USD billions).
          </p>
          <div class="meta" aria-label="Key highlights">
            <span class="legend-pill"><span class="swatch" style="background:#f59e0b"></span>Solar LCOE crosses below fossil range: <strong>2020</strong></span>
            <span class="legend-pill"><span class="swatch" style="background:#60a5fa"></span>Wind LCOE crosses below fossil range: <strong>2019</strong></span>
            <span class="legend-pill"><span class="swatch" style="background:#a78bfa"></span>Battery LCOE: <strong>$1,100 → $102/MWh</strong></span>
          </div>
        </header>
      </section>

      <section class="card reveal" data-reveal aria-label="Main chart">
        <h2 style="font-size:16px; margin-bottom:10px;">Costs fall as capacity rises; subsidies remain large</h2>
        <div class="chart-wrap">
          <canvas id="costCapacitySubsidies" role="img" aria-label="Time series chart: LCOE trends for solar, wind, and batteries; fossil fuel LCOE range; cumulative installed capacity for solar and wind; and total fossil fuel subsidies, 2010 to 2024."></canvas>
        </div>
        <div class="chart-note">
          <div class="annotation-box" aria-label="Crossover annotation">
            <strong>Crossover years highlighted</strong>
            <span>Vertical markers denote first year each renewable’s LCOE drops below the minimum of the fossil cost range (coal/gas CCGT band).</span>
          </div>
          <div>
            Notes: Fossil range is biennial; displayed annually via linear interpolation. Subsidies are total (consumption + production) in nominal USD billions.
            2024 values are preliminary.
          </div>
        </div>
      </section>
    </div>
  </main>

  </main>
  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) {
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          revealObserver.unobserve(e.target);
        }
      });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) {
        console.error('Download failed:', e);
      }
      menu.style.display = '';
    }

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var canvas = document.getElementById(canvasId);
          if (!canvas) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
          canvas.setAttribute('role', 'img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart visualization');
          var ctx = canvas.getContext('2d');
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          canvas.chart = chart;
          return chart;
        } catch (err) {
          console.error('Chart init failed for ' + canvasId + ':', err);
          return null;
        }
      }
    };

    function fmtUSDmwh(v) {
      return '$' + Math.round(v).toLocaleString() + '/MWh';
    }

    function fmtGW(v) {
      if (v >= 1000) return (v/1000).toFixed(1).replace(/\.0$/, '') + 'k GW';
      return Math.round(v).toLocaleString() + ' GW';
    }

    function fmtBn(v) {
      return '$' + Math.round(v).toLocaleString() + 'B';
    }

    function hexToRgba(hex, a) {
      var h = hex.replace('#','');
      var r = parseInt(h.substring(0,2), 16);
      var g = parseInt(h.substring(2,4), 16);
      var b = parseInt(h.substring(4,6), 16);
      return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
    }

    var chartsBuilt = false;

    async function loadData() {
      var res = await fetch('/app/benchmark/source_data.json');
      return await res.json();
    }

    function buildMainChart(source) {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      var isDark = document.documentElement.classList.contains('theme-dark');
      var grid = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(15,23,42,0.10)';
      var tick = isDark ? 'rgba(237,237,237,0.82)' : 'rgba(15,23,42,0.85)';
      var tickSecondary = isDark ? 'rgba(237,237,237,0.55)' : 'rgba(15,23,42,0.55)';

      var lcoe = source.lcoe_trends.data.slice();
      var cap = source.installed_capacity.data.slice();
      var subs = source.fossil_fuel_subsidies.data.slice();
      var fossil = source.fossil_fuel_lcoe_range.data.slice();

      var years = lcoe.map(function(d) { return d.year; });

      var fossilByYear = {};
      fossil.forEach(function(d) {
        var low = Math.min(d.gas_ccgt_low, d.coal_low);
        var high = Math.max(d.gas_ccgt_high, d.coal_high);
        fossilByYear[d.year] = { low: low, high: high };
      });

      // Linear interpolation to annual band
      function interpBand(y) {
        if (fossilByYear[y]) return fossilByYear[y];
        var ys = fossil.map(function(d){ return d.year; }).sort(function(a,b){ return a-b; });
        var prev = null, next = null;
        for (var i=0;i<ys.length;i++) {
          if (ys[i] < y) prev = ys[i];
          if (ys[i] > y) { next = ys[i]; break; }
        }
        if (prev === null) return fossilByYear[ys[0]];
        if (next === null) return fossilByYear[ys[ys.length-1]];
        var t = (y - prev) / (next - prev);
        var a = fossilByYear[prev], b = fossilByYear[next];
        return {
          low: a.low + (b.low - a.low) * t,
          high: a.high + (b.high - a.high) * t
        };
      }

      var fossilLow = years.map(function(y){ return interpBand(y).low; });
      var fossilHigh = years.map(function(y){ return interpBand(y).high; });

      var solar = lcoe.map(function(d){ return d.solar_pv; });
      var wind = lcoe.map(function(d){ return d.onshore_wind; });
      var battery = lcoe.map(function(d){ return d.battery_storage; });

      var solarGW = cap.map(function(d){ return d.solar_pv_gw; });
      var windGW = cap.map(function(d){ return d.onshore_wind_gw; });

      var subsTotal = subs.map(function(d){ return d.total_subsidies_bn; });

      var colors = {
        solar: '#f59e0b',
        wind: '#60a5fa',
        battery: '#a78bfa',
        fossilBand: isDark ? 'rgba(148,163,184,0.14)' : 'rgba(71,85,105,0.14)',
        fossilLine: isDark ? 'rgba(148,163,184,0.55)' : 'rgba(71,85,105,0.55)',
        subsidies: isDark ? 'rgba(244,63,94,0.22)' : 'rgba(225,29,72,0.22)',
        subsidiesBorder: isDark ? 'rgba(244,63,94,0.35)' : 'rgba(225,29,72,0.40)',
        solarCap: '#d97706',
        windCap: '#2563eb'
      };

      var crossoverSolarYear = 2020;
      var crossoverWindYear = 2019;

      var vlinePlugin = {
        id: 'vlinePlugin',
        afterDatasetsDraw: function(chart) {
          var ctx = chart.ctx;
          var xScale = chart.scales.x;
          if (!xScale) return;

          function drawMarker(year, color, label) {
            var idx = years.indexOf(year);
            if (idx === -1) return;
            var x = xScale.getPixelForValue(idx);
            var top = chart.chartArea.top;
            var bottom = chart.chartArea.bottom;

            ctx.save();
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.setLineDash([5,4]);
            ctx.beginPath();
            ctx.moveTo(x, top);
            ctx.lineTo(x, bottom);
            ctx.stroke();
            ctx.setLineDash([]);

            // Label pill
            var padX = 8;
            var padY = 5;
            ctx.font = '600 12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
            var text = label + ' ' + year;
            var tw = ctx.measureText(text).width;
            var bx = Math.min(Math.max(x + 8, chart.chartArea.left + 6), chart.chartArea.right - (tw + padX*2) - 6);
            var by = chart.chartArea.top + 10;
            var bh = 22;

            ctx.fillStyle = isDark ? 'rgba(20,20,20,0.92)' : 'rgba(255,255,255,0.92)';
            ctx.strokeStyle = isDark ? 'rgba(255,255,255,0.10)' : 'rgba(15,23,42,0.12)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            var r = 8;
            ctx.moveTo(bx+r, by);
            ctx.arcTo(bx+tw+padX*2, by, bx+tw+padX*2, by+bh, r);
            ctx.arcTo(bx+tw+padX*2, by+bh, bx, by+bh, r);
            ctx.arcTo(bx, by+bh, bx, by, r);
            ctx.arcTo(bx, by, bx+tw+padX*2, by, r);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            ctx.fillStyle = tick;
            ctx.fillText(text, bx + padX, by + 15);

            // small dot at top
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.arc(x, top + 3, 3, 0, Math.PI*2);
            ctx.fill();

            ctx.restore();
          }

          drawMarker(crossoverWindYear, colors.wind, 'Wind crosses below fossil');
          drawMarker(crossoverSolarYear, colors.solar, 'Solar crosses below fossil');
        }
      };

      var config = {
        type: 'bar',
        data: {
          labels: years.map(String),
          datasets: [
            {
              type: 'bar',
              label: 'Fossil fuel subsidies (total) — nominal USD (B)',
              yAxisID: 'ySubsidy',
              data: subsTotal,
              backgroundColor: colors.subsidies,
              borderColor: colors.subsidiesBorder,
              borderWidth: 1,
              barPercentage: 0.85,
              categoryPercentage: 0.82,
              order: 3
            },
            {
              type: 'line',
              label: 'Fossil cost range (upper bound) — 2023 USD/MWh',
              yAxisID: 'yCost',
              data: fossilHigh,
              borderColor: colors.fossilLine,
              borderWidth: 1,
              pointRadius: 0,
              tension: 0,
              fill: false,
              order: 1
            },
            {
              type: 'line',
              label: 'Fossil cost range (lower bound) — 2023 USD/MWh',
              yAxisID: 'yCost',
              data: fossilLow,
              borderColor: colors.fossilLine,
              borderWidth: 1,
              pointRadius: 0,
              tension: 0,
              fill: { target: '-1' },
              backgroundColor: colors.fossilBand,
              order: 1
            },
            {
              type: 'line',
              label: 'Solar PV LCOE — 2023 USD/MWh',
              yAxisID: 'yCost',
              data: solar,
              borderColor: colors.solar,
              backgroundColor: colors.solar,
              borderWidth: 2,
              pointRadius: 2.2,
              pointHoverRadius: 3.2,
              pointBorderWidth: 0,
              tension: 0.15,
              order: 0
            },
            {
              type: 'line',
              label: 'Onshore wind LCOE — 2023 USD/MWh',
              yAxisID: 'yCost',
              data: wind,
              borderColor: colors.wind,
              backgroundColor: colors.wind,
              borderWidth: 2,
              pointRadius: 2.2,
              pointHoverRadius: 3.2,
              pointBorderWidth: 0,
              tension: 0.15,
              order: 0
            },
            {
              type: 'line',
              label: 'Battery storage LCOE (4h) — 2023 USD/MWh',
              yAxisID: 'yCost',
              data: battery,
              borderColor: colors.battery,
              backgroundColor: colors.battery,
              borderWidth: 2,
              pointRadius: 2.2,
              pointHoverRadius: 3.2,
              pointBorderWidth: 0,
              tension: 0.12,
              order: 0
            },
            {
              type: 'line',
              label: 'Solar PV capacity — cumulative (GW)',
              yAxisID: 'yCap',
              data: solarGW,
              borderColor: colors.solarCap,
              backgroundColor: colors.solarCap,
              borderWidth: 2,
              borderDash: [6,4],
              pointRadius: 0,
              tension: 0.15,
              order: 2
            },
            {
              type: 'line',
              label: 'Onshore wind capacity — cumulative (GW)',
              yAxisID: 'yCap',
              data: windGW,
              borderColor: colors.windCap,
              backgroundColor: colors.windCap,
              borderWidth: 2,
              borderDash: [6,4],
              pointRadius: 0,
              tension: 0.15,
              order: 2
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'index', intersect: false },
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(ctx) {
                  var ds = ctx.dataset;
                  var v = ctx.parsed.y;
                  if (ds.yAxisID === 'ySubsidy') return ds.label + ': ' + fmtBn(v);
                  if (ds.yAxisID === 'yCap') return ds.label + ': ' + fmtGW(v);
                  return ds.label + ': ' + fmtUSDmwh(v);
                }
              }
            },
            legend: {
              position: 'bottom',
              labels: {
                color: tickSecondary,
                usePointStyle: true,
                boxWidth: 10,
                boxHeight: 10,
                padding: 14
              }
            },
            title: {
              display: false
            }
          },
          scales: {
            x: {
              grid: { color: grid },
              ticks: {
                color: tickSecondary,
                maxRotation: 0,
                autoSkip: true,
                callback: function(value, index) {
                  var y = years[index];
                  return (y % 2 === 0) ? String(y) : '';
                }
              },
              title: {
                display: true,
                text: 'Year',
                color: tickSecondary,
                font: { weight: '600' }
              }
            },
            yCost: {
              type: 'logarithmic',
              position: 'left',
              min: 25,
              max: 1300,
              grid: { color: grid },
              ticks: {
                color: tickSecondary,
                callback: function(v) {
                  // Show a curated set of log ticks
                  var allowed = [25, 50, 100, 200, 500, 1000];
                  if (allowed.indexOf(v) !== -1) return '$' + v;
                  return '';
                }
              },
              title: {
                display: true,
                text: 'LCOE (2023 real USD per MWh) — log scale',
                color: tickSecondary,
                font: { weight: '600' }
              }
            },
            yCap: {
              position: 'right',
              grid: { drawOnChartArea: false },
              ticks: {
                color: tickSecondary,
                callback: function(v) { return v >= 1000 ? (v/1000)+'k' : v; }
              },
              title: {
                display: true,
                text: 'Cumulative installed capacity (GW)',
                color: tickSecondary,
                font: { weight: '600' }
              }
            },
            ySubsidy: {
              position: 'right',
              offset: true,
              grid: { drawOnChartArea: false },
              suggestedMin: 0,
              ticks: {
                color: tickSecondary,
                callback: function(v) { return '$' + v; }
              },
              title: {
                display: true,
                text: 'Fossil fuel subsidies (nominal USD billions)',
                color: tickSecondary,
                font: { weight: '600' }
              }
            }
          }
        },
        plugins: [vlinePlugin]
      };

      ChartManager.safeInit('costCapacitySubsidies', config);
    }

    async function buildCharts() {
      if (chartsBuilt) return;
      chartsBuilt = true;
      try {
        var source = await loadData();
        buildMainChart(source);
      } catch (e) {
        console.error('Failed to load/build charts:', e);
      }
    }

    function onThemeChange() {
      chartsBuilt = false;
      buildCharts();
    }

    window.addEventListener('load', buildCharts);
  </script>
</body>
</html>
